insert into public.obavjestenja (slug, tip, naslov, datum, kategorija, sazetak, sadrzaj, slika, objavljeno, placeholder) values ($s$pocela-halka-hifza-amme-dzuza$s$, $s$objava$s$, $s$Počela halka hifza Amme džuza$s$, '2026-10-20'::date, $s$Halke$s$, $s$U novoopremljenoj učionici džamije počela je halka hifza Amme džuza, uz učenje metodom telkina i tefsir.$s$, array[$s$U novoopremljenoj učionici Džamije na Jaliji otpočela je halka hifza Amme džuza. Kur'an se uči i pamti metodom telkina, uz tefsir i razumijevanje kur'anskih poruka.$s$, $s$Molimo Allaha, dželle šanuhu, da ovaj početak učini berićetnim, da polaznicima olakša pamćenje Kur'ana i podari im ustrajnost na putu hifza.$s$, $s$Izvor: zvanični Instagram profil džamije, objava od 20. 10. 2026. (https://www.instagram.com/dzamija_na_jaliji/p/DeuxESdCl8u/).$s$]::text[], null, true, false) on conflict (slug) do nothing;
insert into public.obavjestenja (slug, tip, naslov, datum, kategorija, sazetak, sadrzaj, slika, objavljeno, placeholder) values ($s$hifz-amme-dzuza-za-muskarce$s$, $s$obavjestenje$s$, $s$Hifz Amme džuza metodom telkina uz tefsir — za muškarce$s$, '2026-10-11'::date, $s$Halke$s$, $s$Besplatna halka hifza Amme džuza za muškarce, utorkom između akšama i jacije, od 20. 10. 2026. Predaje hafiz Admir Jašarević.$s$, array[$s$Džamija na Jaliji poziva muškarce na besplatnu halku hifza (učenja napamet) Amme džuza metodom telkina, uz tefsir.$s$, $s$Nastava se održava utorkom, između akšama i jacije, a počinje 20. 10. 2026. Profesor je hafiz Admir Jašarević.$s$, $s$Telkin je metoda u kojoj profesor uči, a polaznici za njim ponavljaju, korak po korak, uz stalno praćenje i ispravljanje — što olakšava pamćenje i učvršćivanje hifza.$s$, $s$Prijave se primaju telefonom; broj je naveden na plakatu u izvornoj objavi.$s$, $s$Izvor: zvanični Instagram profil džamije, objava od 11. 10. 2026. (https://www.instagram.com/dzamija_na_jaliji/p/DeWbvqEqdf2/).$s$]::text[], null, true, false) on conflict (slug) do nothing;
insert into public.obavjestenja (slug, tip, naslov, datum, kategorija, sazetak, sadrzaj, slika, objavljeno, placeholder) values ($s$upis-u-skolu-kurana-za-zene-i-djecu$s$, $s$obavjestenje$s$, $s$Upis u Školu Kur'ana časnog za žene i djecu$s$, '2026-10-11'::date, $s$Halke$s$, $s$Nastava počinje u ponedjeljak 19. 10. 2026: hifz, hifz Amme džuza / hatma, tedžvid te hifz Amme džuza i tilavet za djecu.$s$, array[$s$Otvoren je upis u Školu Kur'ana časnog za žene i djecu u Džamiji na Jaliji. Nastava počinje u ponedjeljak, 19. 10. 2026. Profesorica je Alma Uluč.$s$, $s$Raspored: hifz — ponedjeljak i četvrtak, sa jacije; hifz Amme džuza / hatma — srijeda i subota u 17:00; tedžvid — srijeda i subota u 18:30; hifz Amme džuza i tilavet za djecu — subota u 12:00.$s$, $s$Prijave se primaju telefonom; broj je naveden na plakatu u izvornoj objavi. Kurs je besplatan.$s$, $s$Izvor: zvanični Instagram profil džamije, objava od 11. 10. 2026. (https://www.instagram.com/dzamija_na_jaliji/p/DeWcmb7qyR6/).$s$]::text[], null, true, false) on conflict (slug) do nothing;
insert into public.obavjestenja (slug, tip, naslov, datum, kategorija, sazetak, sadrzaj, slika, objavljeno, placeholder) values ($s$ucenje-sufare-za-zene-djecu-i-muskarce$s$, $s$obavjestenje$s$, $s$Učenje arapskog pisma (sufare) — za žene i djecu i za muškarce$s$, '2026-10-11'::date, $s$Halke$s$, $s$Besplatni kursevi sufare: za žene i djecu (prijave do 16. 10. 2026.) i za muškarce (četvrtkom sa akšama, od 22. 10. 2026.).$s$, array[$s$Džamija na Jaliji organizuje besplatne kurseve učenja arapskog pisma (sufare).$s$, $s$Za žene i djecu: prijave su trajale do petka, 16. 10. 2026. Profesorica je Dženana Hasanović.$s$, $s$Za muškarce: nastava počinje 22. 10. 2026., četvrtkom sa akšama. Profesor je Seid Stupljanin.$s$, $s$Prijave se primaju telefonom; brojevi su navedeni na plakatima u izvornim objavama.$s$, $s$Izvor: zvanični Instagram profil džamije, objave od 11. 10. 2026. (https://www.instagram.com/dzamija_na_jaliji/p/DeWccKUqllX/ i https://www.instagram.com/dzamija_na_jaliji/p/DeWa7utK7Il/).$s$]::text[], null, true, false) on conflict (slug) do nothing;
