insert into public.imami_bio (slug, uloga, bio, slika, potvrdjeno, izvori) values ($s$admir-jasarevic$s$, $s$Hatib i predavač u Džamiji na Jaliji$s$, $s$Hafiz Kur'ana. Drži većinu džumanskih hutbi objavljenih na kanalu Džamije na Jaliji, kao i serijale predavanja — ramazanski tefsir sure Jusuf (2026., svakog jutra prije sabahskog farza) i „Duhovna opskrba vjernika”. Od oktobra 2026. u džamiji vodi halku hifza Amme džuza za muškarce metodom telkina, uz tefsir.$s$, $s$/images/imami/admir-jasarevic.webp$s$, true, $s$[{"naziv":"YouTube kanal „Džamija na Jaliji”","url":"https://www.youtube.com/@D%C5%BEamijanaJaliji/videos"},{"naziv":"Instagram @dzamija_na_jaliji — plakat „Hifz Amme džuza” (11. 10. 2026.)","url":"https://www.instagram.com/dzamija_na_jaliji/p/DeWbvqEqdf2/"},{"naziv":"Fotografija: kadar iz videa „Istinsko popravljanje stanja” (10. 10. 2026.), YouTube kanal „Džamija na Jaliji”","url":"https://www.youtube.com/watch?v=zViIQjXeAd8&t=200s"}]$s$::jsonb) on conflict (slug) do nothing;
insert into public.imami_bio (slug, uloga, bio, slika, potvrdjeno, izvori) values ($s$abdurahman-kujevic$s$, $s$Gost hatib i predavač (halka hadisa)$s$, $s$Hafiz, rođen 1982. u Rožajama. Završio je medresu Gazi Isa-beg u Novom Pazaru i Fakultet hadisa i islamskih nauka na Islamskom univerzitetu u Medini (2006.). Mešihat Islamske zajednice u Srbiji imenovao ga je 2016. za vršioca dužnosti muftije sandžačkog, a na otvaranju Džamije na Jaliji 2024. obratio se kao muftija sandžački. U džamiji drži hutbe i halku hadisa.$s$, $s$/images/imami/abdurahman-kujevic.webp$s$, true, $s$[{"naziv":"Wikipedia — Abdurahman Kujević","url":"https://en.wikipedia.org/wiki/Abdurahman_Kujevi%C4%87"},{"naziv":"Mešihat IZ u Srbiji — Vršilac dužnosti muftije sandžačkog (7. 3. 2016.)","url":"https://mesihat.org/2016/03/07/vrsilac-duznosti-muftija-sandzacki-je-hfz-abdurahman-ef-kujevic/"},{"naziv":"Mešihat IZ u Srbiji — Svečano otvorena džamija na Jaliji (8. 3. 2024.)","url":"https://mesihat.org/2024/03/08/svecano-otvorena-dzamija-na-jaliji/"},{"naziv":"Fotografija: kadar iz videa „Trebamo kvalitetne ljude” (22. 8. 2026.), YouTube kanal „Džamija na Jaliji”","url":"https://www.youtube.com/watch?v=URC-DOi3T-c&t=102s"}]$s$::jsonb) on conflict (slug) do nothing;
insert into public.imami_bio (slug, uloga, bio, slika, potvrdjeno, izvori) values ($s$edin-redzepovic$s$, $s$Gost hatib$s$, $s$Hafiz Kur'ana. Drži džumanske hutbe u Džamiji na Jaliji, a predavanja i u Hasan Čelebi (Arap) džamiji u Novom Pazaru.$s$, $s$/images/imami/edin-redzepovic.webp$s$, true, $s$[{"naziv":"YouTube — hutba „Razumijevanje ibadeta u islamu” (25. 9. 2026.)","url":"https://www.youtube.com/watch?v=uOrHIm0Tmc0"},{"naziv":"Hasan Čelebi (Arap) džamija — Predavanja","url":"https://www.arapdzamija.rs/predavanja"},{"naziv":"Fotografija: kadar iz videa „Razumijevanje ibadeta u islamu” (26. 9. 2026.), YouTube kanal „Džamija na Jaliji”","url":"https://www.youtube.com/watch?v=uOrHIm0Tmc0&t=360s"}]$s$::jsonb) on conflict (slug) do nothing;
insert into public.imami_bio (slug, uloga, bio, slika, potvrdjeno, izvori) values ($s$dzenan-kamesnicanin$s$, $s$Gost hatib$s$, $s$Glavni imam Medžlisa Islamske zajednice Novi Pazar u vrijeme otvaranja Džamije na Jaliji (mart 2024.), kada je vodio program svečanosti. U džamiji je održao džumansku hutbu „Kulturološka pripadnost islamu” (29. 8. 2025.).$s$, $s$/images/imami/dzenan-kamesnicanin.webp$s$, true, $s$[{"naziv":"Mešihat IZ u Srbiji — Svečano otvorena džamija na Jaliji (8. 3. 2024.)","url":"https://mesihat.org/2024/03/08/svecano-otvorena-dzamija-na-jaliji/"},{"naziv":"YouTube — Hutba 29. 8. 2025.","url":"https://www.youtube.com/watch?v=_9qWe3pe_k8"},{"naziv":"Fotografija: kadar iz videa „Kulturološka pripadnost islamu” (30. 8. 2025.), YouTube kanal „Džamija na Jaliji”","url":"https://www.youtube.com/watch?v=_9qWe3pe_k8&t=150s"}]$s$::jsonb) on conflict (slug) do nothing;
insert into public.imami_bio (slug, uloga, bio, slika, potvrdjeno, izvori) values ($s$ferid-fijuljanin$s$, $s$Gost hatib$s$, $s$Hafiz Kur'ana. Održao je džumansku hutbu u Džamiji na Jaliji (25. 7. 2025.), a hutbe drži i u Hasan Čelebi (Arap) džamiji u Novom Pazaru.$s$, $s$/images/imami/ferid-fijuljanin.webp$s$, true, $s$[{"naziv":"YouTube — Hutba 25. 7. 2025.","url":"https://www.youtube.com/watch?v=XyZ9pCBpPB0"},{"naziv":"Hasan Čelebi (Arap) džamija — Hutbe","url":"https://www.arapdzamija.rs/hutbe"},{"naziv":"Fotografija: kadar iz videa „Hutba 25.07.2025.” (27. 7. 2025.), YouTube kanal „Džamija na Jaliji”","url":"https://www.youtube.com/watch?v=XyZ9pCBpPB0&t=150s"}]$s$::jsonb) on conflict (slug) do nothing;
insert into public.imami_bio (slug, uloga, bio, slika, potvrdjeno, izvori) values ($s$zikret-mustafic$s$, $s$Gost predavač$s$, $s$Hafiz Kur'ana. Održao je predavanje „Opasnost javnog razvrata” u Džamiji na Jaliji (2025.), a predaje i u Hasan Čelebi (Arap) džamiji u Novom Pazaru.$s$, $s$/images/imami/zikret-mustafic.webp$s$, true, $s$[{"naziv":"YouTube — Opasnost javnog razvrata","url":"https://www.youtube.com/watch?v=43grkcWOjiQ"},{"naziv":"Hasan Čelebi (Arap) džamija — Predavanja","url":"https://www.arapdzamija.rs/predavanja"},{"naziv":"Fotografija: kadar iz videa „Opasnost javnog razvrata” (23. 7. 2025.), YouTube kanal „Džamija na Jaliji”","url":"https://www.youtube.com/watch?v=43grkcWOjiQ&t=302s"}]$s$::jsonb) on conflict (slug) do nothing;
